spec.expr:
sum by (service) (
  rate(
    http_requests_total{
      service!="",
      status="5xx"
    }[5m]
  )
)
or vector(0)

sum by (service) (
  rate(
    http_requests_total{
      service!="",
      status="4xx"
    }[5m]
  )
)
or vector(0)

histogram_quantile(
  0.95,
  sum by (le, service, handler) (
    rate(
      http_request_duration_seconds_bucket{
        service!="",
        handler!="/metrics"
      }[5m]
    )
  )
)
